"""One-shot scoped scalar seal; preserve every dependency and original inode/mode."""
from pathlib import Path
import datetime,hashlib,json
D=Path(__file__).resolve().parent;R=D.parents[5];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();M=D/'FINAL-MANIFEST-v1.json';assert not M.exists(),'REFUSE_RESEAL'
O=R/json.loads((D/'ACTIVE-v1.json').read_text())['receipt'];C=O/'AUDIT-CERTIFICATE-v2.json';c=json.loads(C.read_text());assert c['status']=='PASS_AUTHOR_RECOVERY_RANGES_AND_FINITE_PRIMITIVES_FULL_SIMULATION_OPEN'
