ready={'version':1,'status':'FROZEN_AUTHOR_RECOVERY_RANGES_FINITE_PRIMITIVES_PERSISTENT_SIMULATION_OPEN_REVIEW_PENDING','canonical_receipt':str(O.relative_to(R)),'canonical_import':'RSCopyBounds','range_import':'RSInterface','namespace_ranges':'OrdinaryDispatch.RecoveryScalar','namespace_bits':'OrdinaryDispatch.RecoveryBits','audit_certificate':str(C.relative_to(R)),'audit_certificate_sha256':sha(C),'source_range_interface':'final_recovery_ranges','source_with_range_interface':'source_bound_and_ranges','state_interface':'descendant_caps','counter_interface':'receipt_field_caps','source_resource':'N=inputResource S<= (treeNodes S+2)^2','labels_colors':'below2^L, original labels explicit; final color transfer uses actual Nodup/partition','fuel':'q=min inputBudget ((leaves S).length-1); every descendant fuel<=q','source_counts':'eventSize(run q)+3<=8*2^(q+1), all five receipt fields bounded below2^(Q+5) ifq<=Q','source_output_sizes':'blocks<=N+1, each block length<=N, flatten<=N*(N+1), cut count/address lengths<=N','width':'scalarWidth N L Q=L+2*labelBits(N+1)+Q+8, mathematical certificate only','finite_primitive_interface':'finite_primitive_work: named concrete copied equality/order/min/subtract/counterAdd<=128*(W+1)','budget_interface':'clipBudget_value and clipBudget_work<=160*(W+1)*(leaves.length+1)','color_interface':'colorBits_value/colorBits_length/colorBits_work<=96*(W+1)*(flatten.length+blocks.length+1)','copy_tree_interface':'copyTree_source_bound<=64*(W+4)*N','copy_output_interface':'copyOutput_source_bound<=32*(W+4)*(N+1)^2','bit_value_premises':['supplied array widths<=W','counter nonoverflow for value equality','source StateCap/OutputCap plus represented word widths for source-relative copies'],'prior_source_envelope':'64*(BudgetOptimization.recoveryEnvelope n+32)*2^q; exactly-once233/100 source absorption preserved','prior_multiplier':64,'prior_exponential_factor':'2^q','new_whole_bit_fee_or_recurrence':False,'full_recovery_bit_execution_proved':False,'runtime_encode_decode_projection_used':False,'supplied_representation_only':True,'native_compiler_IR_correspondence':False,'independent_credit':0,'full_algorithm_base_novelty':'ALL_OPEN','first_missing_primitive':'Recovery-specific persistent represented RWInitial.meterInitial (paid input conversion/leaves/Nodup/fromTree/clipped budget/lifetime); then represented local control and full receipt/materialization simulation','first_gap':str((D/'FIRST-GAP-v1.md').relative_to(R)),'boundary':str((D/'BOUNDARY-v1.md').relative_to(R)),'dependency_rebuilds':0,'compiled_pool_differences':16,'binary_reference_object_pool_imported':False,'owned_binary_primitive_source_derivatives':6,'no_children_peer_messages_or_unfinished_source_reads':True}
(D/'PUBLIC-INTERFACE-v1.json').write_text(json.dumps(ready,indent=2)+'\n')
# Two author prose passes: scope/interface match and adverse-case/limitation match.
texts={n:(D/n).read_text() for n in ['README.md','BOUNDARY-v1.md','FIRST-GAP-v1.md','SOURCE-SHEET-v1.md','PROVENANCE-v1.md','SELF-REVIEW-v1.md']}
for n,s in texts.items():assert 'independent' in s.lower() or n=='SOURCE-SHEET-v1.md'
assert all('open' in texts[n].lower() for n in ['README.md','BOUNDARY-v1.md','FIRST-GAP-v1.md'])
assert 'meterInitial' in texts['FIRST-GAP-v1.md'] and 'lifetime' in texts['BOUNDARY-v1.md']
(D/'AUTHOR-DOCUMENT-CHECKS-v1.json').write_text(json.dumps({'passes':['scope and final named interface match','adverse cases, conditions, exact first missing producer and nonacceptance match'],'independent_credit':0,'prose_sources':[{'path':n,'sha256':sha(D/n)} for n in texts],'result':'PASS_AUTHOR_LIMITED_SCOPE_ONLY'},indent=2)+'\n')
for p in sorted(D.rglob('*')):
 if p.is_file() and '__pycache__' not in p.parts:
  record(p);q=O/'input-snapshot'/p.relative_to(D);q.parent.mkdir(parents=True,exist_ok=True);q.write_bytes(p.read_bytes())
for p in O.rglob('*'):
 if p.is_file() and '__pycache__' not in p.parts:p.chmod(0o444)
files=[{'path':str(p.relative_to(R)),'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(O.rglob('*')) if p.is_file() and '__pycache__' not in p.parts]
runs=[json.loads(p.read_text()) for p in O.glob('*.run.json')]
m={**ready,'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'no_further_writes':True,'no_write_boundary':'Manifest, immutable files, canonical receipt and pinned originals. Continue in new disjoint paths; preserve hashes/modes/inodes.','immutable_files':files,'original_files':list(originals.values()),'source_modules':c['modules'],'stored_new_occurrences':c['stored_occurrences'],'axiom_union':c['axiom_union'],'controls':c['controls'],'source_false_diagnoses':12,'named_positive_checks':17,'same_lineage':True,'skipped':c['skipped'],'maximum_measured_process_seconds':max(r['seconds'] for r in runs),'resource_caps':{'process_seconds':30,'Lean_memory_MiB':3072,'live_disk_floor_GiB':3,'raw_output_MiB':16,'producer_raw_MiB':8,'compressed_total_MiB':256},'audit_scope':'13 owned modules; all stored nonproof/opaque bodies retained; actual full proof reference/AX walks. 712 occurrences. Runtime primitive closure has no mathematical encode/decode/view or Classical.choose. Not all-imported-body, native IR or end-to-end finite-bit simulation.','prior_audit_retained':'v1 679 occurrences/12 modules; finalv2 712/13 with source-relative copy bounds','all_previous_sources_controls_failures_preserved':True}
M.write_text(json.dumps(m,indent=2)+'\n');M.chmod(0o444);h=D/'FINAL-MANIFEST-v1.sha256';h.write_text(sha(M)+'  FINAL-MANIFEST-v1.json\n');h.chmod(0o444)
print('SEALED_RECOVERY_SCALAR_SCOPE',len(files),'readonly members',len(originals),'original records',sha(M))
